query ProjectPickerRelayQuery(
  $owner: String!
  $repo: String!
  $query: String
) {
  repository(owner: $owner, name: $repo) {
    projectsV2(first: 5, query: $query, orderBy: {field: RELEVANCE, direction: DESC}, useFullTermQuery: true) {
      nodes {
        ...ProjectPickerRelay
        id
      }
    }
    recentProjects(first: 5) {
      edges {
        node {
          ...ProjectPickerRelay
          id
        }
      }
    }
    owner {
      __typename
      ... on Organization {
        projectsV2(first: 5, orderBy: {field: RELEVANCE, direction: DESC}, query: $query, useFullTermQuery: true) {
          edges {
            node {
              ...ProjectPickerRelay
              id
            }
          }
        }
        recentProjects(first: 5) {
          edges {
            node {
              ...ProjectPickerRelay
              id
            }
          }
        }
      }
      ... on User {
        projectsV2(first: 5, orderBy: {field: RELEVANCE, direction: DESC}, query: $query, useFullTermQuery: true) {
          edges {
            node {
              ...ProjectPickerRelay
              id
            }
          }
        }
        recentProjects(first: 5) {
          edges {
            node {
              ...ProjectPickerRelay
              id
            }
          }
        }
      }
      id
    }
    id
  }
}

