  $input: UpdateIssueInput!
) {
  updateIssue(input: $input) {
    issue {
      id
      number
      url
      title
      body
      bodyVersion
      assignees(first: 10) {
        nodes {
          id
          login
          name
          avatarUrl
        }
      }
      labels(first: 20) {
        nodes {
          id
          name
          color
          description
        }
      }
      milestone {
        id
        title
        description
        state
      }
      issueType {
        id
        name
        color
        description
      }
      repository {
        databaseId
        id
        name
        owner {
          __typename
          login
          id
        }
      }
      projectItemsNext(first: 20) {
        edges {
          node {
            id
            project {
              id
              title
              closed
              number
              url
              viewerCanUpdate
              hasReachedItemsLimit
            }
          }
        }
      }
    }
    errors {
      __typename
      message
    }
  }
}

ea90e44784b0d402d23a7bd6a9a32876.query:
query useLabelsQueryQuery(
  $owner: String!
  $repo: String!
  $labelNames: String = ""
  $count: Int = 100
) {
  repository(owner: $owner, name: $repo) {
    labels(names: $labelNames, first: $count, orderBy: {field: NAME, direction: ASC}) {
      nodes {
        ...LabelPickerLabel
        ...ItemPickerLabelItem
        id
      }
    }
    id
  }
}

fragment ItemPickerLabelItem on Label {
  id
  color
  name
  nameHTML
  description
  url
}

fragment LabelPickerLabel on Label {
  id
  color
  name
  nameHTML
  description
  url
}

453f03781d915408c3c338e5d346e0be.query:
query TemplatePickerQuery(
  $owner: String!
  $repo: String!
) {
  repository(owner: $owner, name: $repo) {
    issueForms {
      __typename
      ...TemplatePickerForm
    }
    issueTemplates {
      __typename
      ...TemplatePickerTemplate
    }
    id
  }
}

fragment TemplatePickerForm on IssueForm {
  __typename
  filename
  name
  description
}

fragment TemplatePickerTemplate on IssueTemplate {
  __typename
  filename
  name
  about
}

