45538d05afecb94c4759f1703a7f7f06.query:
query IssueSubIssues_NestedQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Issue {
      id
      subIssues(first: 100) {
        nodes {
          ...IssueSubIssues_InnerFragment
          id
        }
      }
    }
    id
  }
}

fragment IssueSubIssues_InnerFragment on Issue {
  id
  title
  titleHTML
  state
  url
  labels(first: 10) {
    nodes {
      id
      name
      color
    }
  }
  assignees(first: 10) {
    totalCount
    edges {
      node {
        id
        login
        avatarUrl
      }
    }
  }
  subIssuesSummary {
    total
    completed
    percentCompleted
  }
  closedByPullRequestsReferences(first: 0, includeClosedPrs: true) {
    totalCount
  }
}

